    def maxScore(self, cardPoints: List[int], k: int) -> int:
        n, w = len(cardPoints), len(cardPoints) - k
        s = best = sum(cardPoints[:w])
        for i in range(w, n):
            s += cardPoints[i] - cardPoints[i - w]
            best = min(best, s)
        return sum(cardPoints) - best

