class Solution:
    def longestSubarray(self, nums: List[int]) -> int:
        lo = zeros = best = 0
        for hi, x in enumerate(nums):
            zeros += x == 0
            while zeros > 1:
                zeros -= nums[lo] == 0
                lo += 1
            best = max(best, hi - lo)          # (hi - lo + 1) - 1 deleted element
        return best

